def uncoveredRanges(intervals, lo, hi):
    res = []
    reach = lo
    for s, e in sorted(intervals):
        if e <= reach:
            continue
        if s > reach:
            if s >= hi:
                break
            res.append([reach, s])
        reach = e
        if reach >= hi:
            return res
    if reach < hi:
        res.append([reach, hi])
    return res
